#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"FAIL %d: %s\n",__LINE__,#x);exit(1);}}while(0)
static char *call(const SourcesConfig *cfg,const char *request,const char *error){char *body=NULL;size_t n;FILE *out=open_memstream(&body,&n);CHECK(out);int rc=sources_dispatch(cfg,request,strlen(request),out);CHECK(!fclose(out));if(rc!=(error?1:0))fprintf(stderr,"response %s\n",body);CHECK(rc==(error?1:0));if(error){Json j;CHECK(json_parse(&j,body,n));char *code=json_string(&j,json_get(&j,json_get(&j,0,"error"),"code"));if(!code||strcmp(code,error))fprintf(stderr,"response %s\n",body);CHECK(code&&!strcmp(code,error));free(code);}return body;}
static char *field(const char *body,const char *name){Json j;CHECK(json_parse(&j,body,strlen(body)));char *text=json_string(&j,json_get(&j,0,name));CHECK(text);return text;}
static int b64(unsigned char c){const char *alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",*p=strchr(alphabet,c);return p?(int)(p-alphabet):0;}
typedef struct {SourcesInferenceConfig *inference;SourcesConfig *source;const char *mode;size_t calls;} Fixture;
static const char *transport(void *context,const SourcesInferenceControl *control,const char *input,size_t bytes,char **result,size_t *length){
    Fixture *f=context;f->calls++;CHECK(control->deadline_monotonic>0);Json request;CHECK(json_parse(&request,input,bytes));char *op=json_string(&request,json_get(&request,0,"op")),*provider=json_string(&request,json_get(&request,0,"provider_id"));CHECK(op&&!strcmp(op,"transcribe")&&provider&&!strcmp(provider,f->inference->provider_id));free(op);free(provider);
    char *data=json_string(&request,json_get(&request,0,"audio_wav_base64"));CHECK(data);size_t n=strlen(data),used=0;unsigned char *wav=malloc(n/4*3);CHECK(wav);for(size_t i=0;i<n;i+=4){int a=b64((unsigned char)data[i]),b=b64((unsigned char)data[i+1]),c=b64((unsigned char)data[i+2]),d=b64((unsigned char)data[i+3]);wav[used++]=(unsigned char)((a<<2)|(b>>4));if(data[i+2]!='=')wav[used++]=(unsigned char)((b<<4)|(c>>2));if(data[i+3]!='=')wav[used++]=(unsigned char)((c<<6)|d);}free(data);CHECK(used>=76&&used<=960044&&!memcmp(wav,"RIFF",4));char digest[65];hash_bytes(wav,used,digest);size_t duration=(used-44)/32;free(wav);
    if(!strcmp(f->mode,"unavailable"))return "transport_failure";
    if(!strcmp(f->mode,"deadline"))return "deadline_exceeded";
    if(!strcmp(f->mode,"busy")){*result=strdup("{\"contract_version\":1,\"error\":{\"code\":\"busy\"}}");CHECK(*result);*length=strlen(*result);return NULL;}
    if(!strcmp(f->mode,"cancel")){char *cancelled=call(f->source,"{\"contract_version\":1,\"op\":\"operation_cancel\",\"operation_id\":\"cancel-transcript\"}",NULL);CHECK(strstr(cancelled,"true"));free(cancelled);CHECK(control->cancelled&&control->cancelled(control->cancellation));return "cancelled";}
    if(!strcmp(f->mode,"wrong-input"))memset(digest,'0',64);
    size_t count=!strcmp(f->mode,"many")?128:1;char text[1024];size_t text_bytes=0;for(size_t i=0;i<count;i++){if(i)text[text_bytes++]='\n';text[text_bytes++]='x';}text[text_bytes]=0;
    FILE *out=open_memstream(result,length);CHECK(out);fprintf(out,"{\"contract_version\":1,\"provider_id\":\"%s\",\"kind\":\"%s\",\"artifact_type\":\"transcript\",\"language\":\"en\",\"input_sha256\":\"%s\",\"duration_ms\":%zu,\"text\":",f->inference->provider_id,!strcmp(f->mode,"literal")?"literal":"derived",digest,duration);json_quote(out,text,text_bytes);fputs(",\"segments\":[",out);
    for(size_t i=0;i<count;i++){if(i)fputc(',',out);fprintf(out,"{\"start_ms\":%zu,\"end_ms\":%zu,\"text\":\"%s\"}",i*10,!strcmp(f->mode,"late")?duration+1:i*10+5,!strcmp(f->mode,"mismatch")?"y":"x");}
    fprintf(out,"],\"coverage\":{\"status\":\"partial\",\"reason\":\"speech_recognition_uncertain\"},\"provenance\":{\"engine\":\"whisper.cpp\",\"engine_sha256\":\"%s\",\"model_sha256\":\"%s\",\"coordinate_space\":\"input_audio_milliseconds\",\"timestamp_policy\":\"%s\"}}",f->inference->engine_sha256,!strcmp(f->mode,"wrong-model")?f->inference->engine_sha256:f->inference->model_sha256,!strcmp(f->mode,"wrong-policy")?"unbounded":"whisper_20ms_end_clipped_to_input");CHECK(!fclose(out));return NULL;
}
static void put32(unsigned char *p,uint32_t n){for(size_t i=0;i<4;i++)p[i]=(unsigned char)(n>>(i*8));}
static char *request(const char *source,size_t start,size_t end,const char *id){char body[1024];snprintf(body,sizeof(body),"{\"contract_version\":1,\"op\":\"transcribe_audio\",\"source_id\":\"%s\",\"version\":\"%s\",\"start_ms\":%zu,\"end_ms\":%zu%s%s%s}",source,source,start,end,id?",\"operation_id\":\"":"",id?id:"",id?"\"":"");return strdup(body);}
static int remove_file(const char *path,const struct stat *s,int type,struct FTW *walk){(void)s;(void)type;(void)walk;return remove(path);}
