    char engine[65],model[65];memset(engine,'a',64);memset(model,'b',64);engine[64]=model[64]=0;Fixture fixture={.mode="ok"};SourcesInferenceConfig inference={.provider_id="fixture-whisper-v1",.engine_sha256=engine,.model_sha256=model,.call=transport,.context=&fixture};SourcesConfig cfg={.root=root,.state=state,.owner="alice",.inference=&inference};fixture.inference=&inference;fixture.source=&cfg;
    char *body=call(&cfg,"{\"contract_version\":1,\"op\":\"register_audio\",\"path\":\"audio.wav\"}",NULL),*source=field(body,"source_id");free(body);
    char *input=request(source,1000,2000,"first-transcript"),*saved=call(&cfg,input,NULL);CHECK(fixture.calls==1&&strstr(saved,"\"kind\":\"derived\"")&&strstr(saved,"speech_recognition_uncertain")&&strstr(saved,"\"start_ms\":1000,\"end_ms\":1005"));CHECK(!strstr(saved,"evidence_id"));body=call(&cfg,input,NULL);CHECK(!strcmp(saved,body)&&fixture.calls==1);free(body);free(input);
    CHECK(!unlink(path));SourcesConfig offline=cfg;offline.root=NULL;inference.call=NULL;input=request(source,1000,2000,NULL);body=call(&offline,input,NULL);CHECK(fixture.calls==1&&strstr(body,"source_time_ms"));free(body);free(input);inference.call=transport;
    SourcesConfig foreign=offline;foreign.owner="bob";input=request(source,1000,2000,NULL);body=call(&foreign,input,"unknown_source");CHECK(fixture.calls==1);free(body);free(input);
