    fixture.mode="many";input=request(source,18500,19800,"many-cues");body=call(&offline,input,NULL);Json parsed;CHECK(json_parse(&parsed,body,strlen(body)));int list=json_get(&parsed,0,"segments");CHECK(list>=0&&parsed.tokens[list].count==128);CHECK(strstr(body,"\"start_ms\":19770,\"end_ms\":19775"));free(body);free(input);
    fixture.mode="cancel";input=request(source,20000,21000,"cancel-transcript");body=call(&offline,input,"cancelled");free(body);fixture.mode="ok";body=call(&offline,input,"cancelled");free(body);free(input);input=request(source,20000,21000,NULL);size_t previous=fixture.calls;body=call(&offline,input,NULL);CHECK(fixture.calls==previous+1);free(body);free(input);
    SourcesConfig limited=offline;limited.cache_limit=1;input=request(source,22000,23000,NULL);previous=fixture.calls;body=call(&limited,input,"cache_limit");CHECK(fixture.calls==previous);free(body);free(input);
    char changed_model[65];memset(changed_model,'c',64);changed_model[64]=0;inference.model_sha256=changed_model;input=request(source,1000,2000,NULL);previous=fixture.calls;body=call(&offline,input,NULL);CHECK(fixture.calls==previous+1);char *original_artifact=field(saved,"artifact_id"),*changed_artifact=field(body,"artifact_id");CHECK(strcmp(original_artifact,changed_artifact));free(changed_artifact);free(body);free(input);inference.model_sha256=model;
    sqlite3 *fixture_db=NULL;CHECK(sqlite3_open(database,&fixture_db)==SQLITE_OK);sqlite3_stmt *selected=NULL;CHECK(sqlite3_prepare_v2(fixture_db,"SELECT key,response FROM prepared_artifacts WHERE json_extract(response,'$.artifact_id')=?",-1,&selected,NULL)==SQLITE_OK);sqlite3_bind_text(selected,1,original_artifact,-1,SQLITE_TRANSIENT);CHECK(sqlite3_step(selected)==SQLITE_ROW);char *selected_key=strdup((const char*)sqlite3_column_text(selected,0)),*original_body=strdup((const char*)sqlite3_column_text(selected,1));CHECK(selected_key&&original_body);sqlite3_finalize(selected);char *altered=strdup(original_body),*proof=strstr(altered,model);CHECK(proof);memcpy(proof,engine,64);char forged_digest[65];hash_bytes(altered,strlen(altered),forged_digest);CHECK(sqlite3_prepare_v2(fixture_db,"UPDATE prepared_artifacts SET response=?,digest=? WHERE key=?",-1,&selected,NULL)==SQLITE_OK);sqlite3_bind_text(selected,1,altered,-1,SQLITE_TRANSIENT);sqlite3_bind_text(selected,2,forged_digest,-1,SQLITE_TRANSIENT);sqlite3_bind_text(selected,3,selected_key,-1,SQLITE_TRANSIENT);CHECK(sqlite3_step(selected)==SQLITE_DONE);sqlite3_finalize(selected);CHECK(sqlite3_close(fixture_db)==SQLITE_OK);free(altered);free(selected_key);free(original_body);free(original_artifact);
